"""FastAPI application for the sh1x server wiki."""
from __future__ import annotations

import logging
from contextlib import asynccontextmanager

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

from . import models  # noqa: F401  (import registers the tables on Base.metadata)
from .config import get_settings
from .db import Base, dispose, engine
from .routers import auth, pages, reference, search, spaces

log = logging.getLogger("wiki")


@asynccontextmanager
async def lifespan(_: FastAPI):
    settings = get_settings()
    if settings.auto_create_schema:
        async with engine().begin() as connection:
            await connection.run_sync(Base.metadata.create_all)
        log.info("schema ready")
    yield
    await dispose()


def create_app() -> FastAPI:
    settings = get_settings()
    app = FastAPI(
        title=settings.site_name,
        description=(
            "Engineering reference for the sh1x server (Call of Duty Online "
            "Closed Alpha Server), a CoD4x fork. Authored pages are editable by "
            "signed-in editors; the source reference is regenerated by the indexer."
        ),
        version="1.0.0",
        lifespan=lifespan,
    )
    app.add_middleware(
        CORSMiddleware,
        allow_origins=settings.origins,
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["*"],
    )
    for router in (auth.router, spaces.router, pages.router, reference.router, search.router):
        app.include_router(router, prefix="/api")

    @app.get("/api/health", tags=["meta"])
    async def health() -> dict:
        return {"status": "ok"}

    return app


app = create_app()
